// Builds Decap CMS articles (content/articles/*.md) into static pages.
//
//   node scripts/build-articles.mjs
//
// For each non-draft article it writes posts/<category>/<url_slug>.html using the
// same layout as the hand-written articles, and regenerates the "new articles"
// list in posts/Articles.html (between the articles:new markers).
// Pages generated by an earlier run whose source was deleted are removed; the
// list of generated files is kept in scripts/generated.json.

import { readdir, readFile, writeFile, rm, access } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import matter from "gray-matter";
import { marked } from "marked";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SRC_DIR = path.join(ROOT, "content", "articles");
const POSTS_DIR = path.join(ROOT, "posts");
const MANIFEST = path.join(ROOT, "scripts", "generated.json");
const LIST_FILE = path.join(POSTS_DIR, "Articles.html");
const LIST_START = "<!-- articles:new:start -->";
const LIST_END = "<!-- articles:new:end -->";
const SLUG_RE = /^[a-z0-9-]+$/;

const exists = (p) => access(p).then(() => true, () => false);
const esc = (s) =>
  String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

function formatDate(value) {
  if (!value) return "";
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("he-IL", {
    year: "numeric",
    month: "long",
    day: "numeric",
    timeZone: "Asia/Jerusalem",
  });
}

function articlePage({ title, description, date, body, depth }) {
  // Pages sit in posts/<category>/, so the shared assets are two levels up.
  const up = "../".repeat(depth);
  return `<!DOCTYPE html>
<html dir="rtl" lang="he">
<head>
<meta charset="utf-8"/>
<meta content="width=device-width, initial-scale=1" name="viewport"/>
<title>${esc(title)} · מלחמת תורה</title>
<meta content="${esc(description)}" name="description"/>
<link href="https://fonts.googleapis.com" rel="preconnect"/>
<link crossorigin="" href="https://fonts.gstatic.com" rel="preconnect"/>
<link href="https://fonts.googleapis.com/css2?family=Heebo:wght@400;500;700;800&amp;display=swap" rel="stylesheet"/>
<link href="${up}assets/article.css" rel="stylesheet"/>
</head>
<body>
<main class="wrap article">
<nav class="back-top" aria-label="ניווט"><a class="back-link" href="../Articles.html">חזרה למאמרים</a></nav>
<article>
<h1>${esc(title)}</h1>
${date ? `<p class="article-meta">${esc(date)}</p>\n` : ""}<div class="post-body">
${body}
</div>
</article>
</main>
<footer class="wrap foot"><a class="back-link" href="../Articles.html">חזרה למאמרים</a></footer>
</body>
</html>
`;
}

async function loadArticles() {
  const files = (await readdir(SRC_DIR)).filter((f) => f.endsWith(".md")).sort();
  const articles = [];
  const seenOutputs = new Set();

  for (const file of files) {
    const raw = await readFile(path.join(SRC_DIR, file), "utf8");
    const { data, content } = matter(raw);
    if (data.draft === true) continue;

    for (const key of ["title", "url_slug", "category"]) {
      if (!data[key]) throw new Error(`${file}: missing field "${key}"`);
    }
    if (!SLUG_RE.test(data.url_slug)) {
      throw new Error(`${file}: url_slug "${data.url_slug}" may only contain a-z, 0-9 and "-"`);
    }
    if (!(await exists(path.join(POSTS_DIR, data.category)))) {
      throw new Error(`${file}: unknown category folder "posts/${data.category}"`);
    }

    const relOut = path.join("posts", data.category, `${data.url_slug}.html`);
    if (seenOutputs.has(relOut)) throw new Error(`${file}: duplicate output ${relOut}`);
    seenOutputs.add(relOut);

    const body = (await marked.parse(content))
      // Decap stores uploads as site-absolute paths; make them relative to the page.
      .replace(/(src|href)="\/assets\//g, `$1="../../assets/`);

    articles.push({
      title: String(data.title),
      description: String(data.description ?? ""),
      category: String(data.category),
      slug: data.url_slug,
      date: data.date ? new Date(data.date) : null,
      body,
      relOut,
    });
  }

  articles.sort((a, b) => (b.date?.getTime() ?? 0) - (a.date?.getTime() ?? 0));
  return articles;
}

async function writeArticles(articles) {
  let previous = [];
  if (await exists(MANIFEST)) {
    previous = JSON.parse(await readFile(MANIFEST, "utf8"));
  }
  const current = new Set(articles.map((a) => a.relOut));

  // Refuse to overwrite a hand-written page that this build did not create.
  for (const a of articles) {
    const abs = path.join(ROOT, a.relOut);
    if ((await exists(abs)) && !previous.includes(a.relOut)) {
      throw new Error(`${a.relOut} already exists and was not generated; choose another url_slug`);
    }
  }

  for (const a of articles) {
    const html = articlePage({
      title: a.title,
      description: a.description,
      date: formatDate(a.date),
      body: a.body,
      depth: 2,
    });
    await writeFile(path.join(ROOT, a.relOut), html, "utf8");
  }

  for (const old of previous) {
    if (!current.has(old)) await rm(path.join(ROOT, old), { force: true });
  }

  await writeFile(MANIFEST, JSON.stringify([...current].sort(), null, 2) + "\n", "utf8");
}

async function updateListing(articles) {
  const items = articles.map((a) => {
    const desc = a.description ? `<span class="desc">${esc(a.description)}</span>` : "";
    return `<li><a href="${esc(a.category)}/${esc(a.slug)}.html">${esc(a.title)}</a>${desc}</li>`;
  });
  const block = items.length
    ? `<section class="collection">\n<h2>מאמרים חדשים</h2>\n<ul class="links">\n${items.join("\n")}\n</ul>\n</section>\n`
    : "";

  const html = await readFile(LIST_FILE, "utf8");
  const s = html.indexOf(LIST_START);
  const e = html.indexOf(LIST_END);
  if (s === -1 || e === -1 || e < s) {
    throw new Error(`posts/Articles.html is missing the "${LIST_START}" / "${LIST_END}" markers`);
  }
  const next = html.slice(0, s + LIST_START.length) + "\n" + block + html.slice(e);
  await writeFile(LIST_FILE, next, "utf8");
}

const articles = await loadArticles();
await writeArticles(articles);
await updateListing(articles);
console.log(`Built ${articles.length} article(s).`);
